# ! [doc = " Checks that meta-variables in macro definition are correctly declared and used."] # ! [doc = ""] # ! [doc = " # What is checked"] # ! [doc = ""] # ! [doc = " ## Meta-variables must not be bound twice"] # ! [doc = ""] # ! [doc = " ```compile_fail"] # ! [doc = " macro_rules! foo { ($x:tt $x:tt) => { $x }; }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " This check is sound (no false-negative) and complete (no false-positive)."] # ! [doc = ""] # ! [doc = " ## Meta-variables must not be free"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " macro_rules! foo { () => { $x }; }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " This check is also done at macro instantiation but only if the branch is taken."] # ! [doc = ""] # ! [doc = " ## Meta-variables must repeat at least as many times as their binder"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " macro_rules! foo { ($($x:tt)*) => { $x }; }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " This check is also done at macro instantiation but only if the branch is taken."] # ! [doc = ""] # ! [doc = " ## Meta-variables must repeat with the same Kleene operators as their binder"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " macro_rules! foo { ($($x:tt)+) => { $($x)* }; }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " This check is not done at macro instantiation."] # ! [doc = ""] # ! [doc = " # Disclaimer"] # ! [doc = ""] # ! [doc = " In the presence of nested macros (a macro defined in a macro), those checks may have false"] # ! [doc = " positives and false negatives. We try to detect those cases by recognizing potential macro"] # ! [doc = " definitions in RHSes, but nested macros may be hidden through the use of particular values of"] # ! [doc = " meta-variables."] # ! [doc = ""] # ! [doc = " ## Examples of false positive"] # ! [doc = ""] # ! [doc = " False positives can come from cases where we don't recognize a nested macro, because it depends"] # ! [doc = " on particular values of meta-variables. In the following example, we think both instances of"] # ! [doc = " `$x` are free, which is a correct statement if `$name` is anything but `macro_rules`. But when"] # ! [doc = " `$name` is `macro_rules`, like in the instantiation below, then `$x:tt` is actually a binder of"] # ! [doc = " the nested macro and `$x` is bound to it."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " macro_rules! foo { ($name:ident) => { $name! bar { ($x:tt) => { $x }; } }; }"] # ! [doc = " foo!(macro_rules);"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " False positives can also come from cases where we think there is a nested macro while there"] # ! [doc = " isn't. In the following example, we think `$x` is free, which is incorrect because `bar` is not"] # ! [doc = " a nested macro since it is not evaluated as code by `stringify!`."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " macro_rules! foo { () => { stringify!(macro_rules! bar { () => { $x }; }) }; }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ## Examples of false negative"] # ! [doc = ""] # ! [doc = " False negatives can come from cases where we don't recognize a meta-variable, because it depends"] # ! [doc = " on particular values of meta-variables. In the following examples, we don't see that if `$d` is"] # ! [doc = " instantiated with `$` then `$d z` becomes `$z` in the nested macro definition and is thus a free"] # ! [doc = " meta-variable. Note however, that if `foo` is instantiated, then we would check the definition"] # ! [doc = " of `bar` and would see the issue."] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " macro_rules! foo { ($d:tt) => { macro_rules! bar { ($y:tt) => { $d z }; } }; }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " # How it is checked"] # ! [doc = ""] # ! [doc = " There are 3 main functions: `check_binders`, `check_occurrences`, and `check_nested_macro`. They"] # ! [doc = " all need some kind of environment."] # ! [doc = ""] # ! [doc = " ## Environments"] # ! [doc = ""] # ! [doc = " Environments are used to pass information."] # ! [doc = ""] # ! [doc = " ### From LHS to RHS"] # ! [doc = ""] # ! [doc = " When checking a LHS with `check_binders`, we produce (and use) an environment for binders,"] # ! [doc = " namely `Binders`. This is a mapping from binder name to information about that binder: the span"] # ! [doc = " of the binder for error messages and the stack of Kleene operators under which it was bound in"] # ! [doc = " the LHS."] # ! [doc = ""] # ! [doc = " This environment is used by both the LHS and RHS. The LHS uses it to detect duplicate binders."] # ! [doc = " The RHS uses it to detect the other errors."] # ! [doc = ""] # ! [doc = " ### From outer macro to inner macro"] # ! [doc = ""] # ! [doc = " When checking the RHS of an outer macro and we detect a nested macro definition, we push the"] # ! [doc = " current state, namely `MacroState`, to an environment of nested macro definitions. Each state"] # ! [doc = " stores the LHS binders when entering the macro definition as well as the stack of Kleene"] # ! [doc = " operators under which the inner macro is defined in the RHS."] # ! [doc = ""] # ! [doc = " This environment is a stack representing the nesting of macro definitions. As such, the stack of"] # ! [doc = " Kleene operators under which a meta-variable is repeating is the concatenation of the stacks"] # ! [doc = " stored when entering a macro definition starting from the state in which the meta-variable is"] # ! [doc = " bound."] use split_decls_genesis :: ourprelude :: * ; use rustc_ast :: token :: { Delimiter , IdentIsRaw , Token , TokenKind } ; use rustc_ast :: { DUMMY_NODE_ID , NodeId } ; use rustc_data_structures :: fx :: FxHashMap ; use rustc_errors :: MultiSpan ; use rustc_lint_defs :: BuiltinLintDiag ; use rustc_session :: lint :: builtin :: META_VARIABLE_MISUSE ; use rustc_session :: parse :: ParseSess ; use rustc_span :: { ErrorGuaranteed , MacroRulesNormalizedIdent , Span , kw } ; use smallvec :: SmallVec ; use crate :: errors ; use crate :: mbe :: { KleeneToken , TokenTree } ; #[doc = " Stack represented as linked list."] #[doc = ""] #[doc = " Those are used for environments because they grow incrementally and are not mutable."] enum Stack < 'a , T > { #[doc = " Empty stack."] Empty , #[doc = " A non-empty stack."] Push { #[doc = " The top element."] top : T , #[doc = " The previous elements."] prev : & 'a Stack < 'a , T > , } , } impl < 'a , T > Stack < 'a , T > { #[doc = " Returns whether a stack is empty."] fn is_empty (& self) -> bool { matches ! (* self , Stack :: Empty) } #[doc = " Returns a new stack with an element of top."] fn push (& 'a self , top : T) -> Stack < 'a , T > { Stack :: Push { top , prev : self } } } impl < 'a , T > Iterator for & 'a Stack < 'a , T > { type Item = & 'a T ; fn next (& mut self) -> Option < & 'a T > { match self { Stack :: Empty => None , Stack :: Push { top , prev } => { * self = prev ; Some (top) } } } } impl From < & Stack < '_ , KleeneToken > > for SmallVec < [KleeneToken ; 1] > { fn from (ops : & Stack < '_ , KleeneToken >) -> SmallVec < [KleeneToken ; 1] > { let mut ops : SmallVec < [KleeneToken ; 1] > = ops . cloned () . collect () ; ops . reverse () ; ops } } #[doc = " Information attached to a meta-variable binder in LHS."] struct BinderInfo { #[doc = " The span of the meta-variable in LHS."] span : Span , #[doc = " The stack of Kleene operators (outermost first)."] ops : SmallVec < [KleeneToken ; 1] > , } #[doc = " An environment of meta-variables to their binder information."] type Binders = FxHashMap < MacroRulesNormalizedIdent , BinderInfo > ; #[doc = " The state at which we entered a macro definition in the RHS of another macro definition."] struct MacroState < 'a > { #[doc = " The binders of the branch where we entered the macro definition."] binders : & 'a Binders , #[doc = " The stack of Kleene operators (outermost first) where we entered the macro definition."] ops : SmallVec < [KleeneToken ; 1] > , } #[doc = " Checks that meta-variables are used correctly in one rule of a macro definition."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `psess` is used to emit diagnostics and lints"] #[doc = " - `node_id` is used to emit lints"] #[doc = " - `args`, `lhs`, and `rhs` represent the rule"] pub (super) fn check_meta_variables (psess : & ParseSess , node_id : NodeId , args : Option < & TokenTree > , lhs : & TokenTree , rhs : & TokenTree ,) -> Result < () , ErrorGuaranteed > { let mut guar = None ; let mut binders = Binders :: default () ; if let Some (args) = args { check_binders (psess , node_id , args , & Stack :: Empty , & mut binders , & Stack :: Empty , & mut guar) ; } check_binders (psess , node_id , lhs , & Stack :: Empty , & mut binders , & Stack :: Empty , & mut guar) ; check_occurrences (psess , node_id , rhs , & Stack :: Empty , & binders , & Stack :: Empty , & mut guar) ; guar . map_or (Ok (()) , Err) } #[doc = " Checks `lhs` as part of the LHS of a macro definition, extends `binders` with new binders, and"] #[doc = " sets `valid` to false in case of errors."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `psess` is used to emit diagnostics and lints"] #[doc = " - `node_id` is used to emit lints"] #[doc = " - `lhs` is checked as part of a LHS"] #[doc = " - `macros` is the stack of possible outer macros"] #[doc = " - `binders` contains the binders of the LHS"] #[doc = " - `ops` is the stack of Kleene operators from the LHS"] #[doc = " - `guar` is set in case of errors"] fn check_binders (psess : & ParseSess , node_id : NodeId , lhs : & TokenTree , macros : & Stack < '_ , MacroState < '_ > > , binders : & mut Binders , ops : & Stack < '_ , KleeneToken > , guar : & mut Option < ErrorGuaranteed > ,) { match * lhs { TokenTree :: Token (..) => { } TokenTree :: MetaVar (span , name) => { if macros . is_empty () { psess . dcx () . span_bug (span , "unexpected MetaVar in lhs") ; } let name = MacroRulesNormalizedIdent :: new (name) ; if let Some (prev_info) = binders . get (& name) { let mut span = MultiSpan :: from_span (span) ; span . push_span_label (prev_info . span , "previous declaration") ; buffer_lint (psess , span , node_id , BuiltinLintDiag :: DuplicateMatcherBinding) ; } else if get_binder_info (macros , binders , name) . is_none () { binders . insert (name , BinderInfo { span , ops : ops . into () }) ; } else { check_occurrences (psess , node_id , lhs , macros , binders , ops , guar) ; } } TokenTree :: MetaVarDecl { span , name , .. } => { if ! macros . is_empty () { psess . dcx () . span_bug (span , "unexpected MetaVarDecl in nested lhs") ; } let name = MacroRulesNormalizedIdent :: new (name) ; if let Some (prev_info) = get_binder_info (macros , binders , name) { * guar = Some (psess . dcx () . emit_err (errors :: DuplicateMatcherBinding { span , prev : prev_info . span }) ,) ; } else { binders . insert (name , BinderInfo { span , ops : ops . into () }) ; } } TokenTree :: MetaVarExpr (..) => { } TokenTree :: Delimited (.. , ref del) => { for tt in & del . tts { check_binders (psess , node_id , tt , macros , binders , ops , guar) ; } } TokenTree :: Sequence (_ , ref seq) => { let ops = ops . push (seq . kleene) ; for tt in & seq . tts { check_binders (psess , node_id , tt , macros , binders , & ops , guar) ; } } } } #[doc = " Returns the binder information of a meta-variable."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `macros` is the stack of possible outer macros"] #[doc = " - `binders` contains the current binders"] #[doc = " - `name` is the name of the meta-variable we are looking for"] fn get_binder_info < 'a > (mut macros : & 'a Stack < 'a , MacroState < 'a > > , binders : & 'a Binders , name : MacroRulesNormalizedIdent ,) -> Option < & 'a BinderInfo > { binders . get (& name) . or_else (| | macros . find_map (| state | state . binders . get (& name))) } #[doc = " Checks `rhs` as part of the RHS of a macro definition and sets `valid` to false in case of"] #[doc = " errors."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `psess` is used to emit diagnostics and lints"] #[doc = " - `node_id` is used to emit lints"] #[doc = " - `rhs` is checked as part of a RHS"] #[doc = " - `macros` is the stack of possible outer macros"] #[doc = " - `binders` contains the binders of the associated LHS"] #[doc = " - `ops` is the stack of Kleene operators from the RHS"] #[doc = " - `guar` is set in case of errors"] fn check_occurrences (psess : & ParseSess , node_id : NodeId , rhs : & TokenTree , macros : & Stack < '_ , MacroState < '_ > > , binders : & Binders , ops : & Stack < '_ , KleeneToken > , guar : & mut Option < ErrorGuaranteed > ,) { match * rhs { TokenTree :: Token (..) => { } TokenTree :: MetaVarDecl { span , .. } => { psess . dcx () . span_bug (span , "unexpected MetaVarDecl in rhs") } TokenTree :: MetaVar (span , name) => { let name = MacroRulesNormalizedIdent :: new (name) ; check_ops_is_prefix (psess , node_id , macros , binders , ops , span , name) ; } TokenTree :: MetaVarExpr (dl , ref mve) => { mve . for_each_metavar (() , | _ , ident | { let name = MacroRulesNormalizedIdent :: new (* ident) ; check_ops_is_prefix (psess , node_id , macros , binders , ops , dl . entire () , name) ; }) ; } TokenTree :: Delimited (.. , ref del) => { check_nested_occurrences (psess , node_id , & del . tts , macros , binders , ops , guar) ; } TokenTree :: Sequence (_ , ref seq) => { let ops = ops . push (seq . kleene) ; check_nested_occurrences (psess , node_id , & seq . tts , macros , binders , & ops , guar) ; } } } #[doc = " Represents the processed prefix of a nested macro."] #[derive (Clone , Copy , PartialEq , Eq)] enum NestedMacroState { #[doc = " Nothing that matches a nested macro definition was processed yet."] Empty , #[doc = " The token `macro_rules` was processed."] MacroRules , #[doc = " The tokens `macro_rules!` were processed."] MacroRulesBang , #[doc = " The tokens `macro_rules!` followed by a name were processed. The name may be either directly"] #[doc = " an identifier or a meta-variable (that hopefully would be instantiated by an identifier)."] MacroRulesBangName , #[doc = " The keyword `macro` was processed."] Macro , #[doc = " The keyword `macro` followed by a name was processed."] MacroName , #[doc = " The keyword `macro` followed by a name and a token delimited by parentheses was processed."] MacroNameParen , } #[doc = " Checks `tts` as part of the RHS of a macro definition, tries to recognize nested macro"] #[doc = " definitions, and sets `valid` to false in case of errors."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `psess` is used to emit diagnostics and lints"] #[doc = " - `node_id` is used to emit lints"] #[doc = " - `tts` is checked as part of a RHS and may contain macro definitions"] #[doc = " - `macros` is the stack of possible outer macros"] #[doc = " - `binders` contains the binders of the associated LHS"] #[doc = " - `ops` is the stack of Kleene operators from the RHS"] #[doc = " - `guar` is set in case of errors"] fn check_nested_occurrences (psess : & ParseSess , node_id : NodeId , tts : & [TokenTree] , macros : & Stack < '_ , MacroState < '_ > > , binders : & Binders , ops : & Stack < '_ , KleeneToken > , guar : & mut Option < ErrorGuaranteed > ,) { let mut state = NestedMacroState :: Empty ; let nested_macros = macros . push (MacroState { binders , ops : ops . into () }) ; let mut nested_binders = Binders :: default () ; for tt in tts { match (state , tt) { (NestedMacroState :: Empty , & TokenTree :: Token (Token { kind : TokenKind :: Ident (name , IdentIsRaw :: No) , .. }) ,) => { if name == kw :: MacroRules { state = NestedMacroState :: MacroRules ; } else if name == kw :: Macro { state = NestedMacroState :: Macro ; } } (NestedMacroState :: MacroRules , & TokenTree :: Token (Token { kind : TokenKind :: Bang , .. }) ,) => { state = NestedMacroState :: MacroRulesBang ; } (NestedMacroState :: MacroRulesBang , & TokenTree :: Token (Token { kind : TokenKind :: Ident (..) , .. }) ,) => { state = NestedMacroState :: MacroRulesBangName ; } (NestedMacroState :: MacroRulesBang , & TokenTree :: MetaVar (..)) => { state = NestedMacroState :: MacroRulesBangName ; check_occurrences (psess , node_id , tt , macros , binders , ops , guar) ; } (NestedMacroState :: MacroRulesBangName , TokenTree :: Delimited (.. , del)) | (NestedMacroState :: MacroName , TokenTree :: Delimited (.. , del)) if del . delim == Delimiter :: Brace => { let macro_rules = state == NestedMacroState :: MacroRulesBangName ; state = NestedMacroState :: Empty ; let rest = check_nested_macro (psess , node_id , macro_rules , & del . tts , & nested_macros , guar) ; check_nested_occurrences (psess , node_id , & del . tts [rest ..] , macros , binders , ops , guar ,) ; } (NestedMacroState :: Macro , & TokenTree :: Token (Token { kind : TokenKind :: Ident (..) , .. }) ,) => { state = NestedMacroState :: MacroName ; } (NestedMacroState :: Macro , & TokenTree :: MetaVar (..)) => { state = NestedMacroState :: MacroName ; check_occurrences (psess , node_id , tt , macros , binders , ops , guar) ; } (NestedMacroState :: MacroName , TokenTree :: Delimited (.. , del)) if del . delim == Delimiter :: Parenthesis => { state = NestedMacroState :: MacroNameParen ; nested_binders = Binders :: default () ; check_binders (psess , node_id , tt , & nested_macros , & mut nested_binders , & Stack :: Empty , guar ,) ; } (NestedMacroState :: MacroNameParen , TokenTree :: Delimited (.. , del)) if del . delim == Delimiter :: Brace => { state = NestedMacroState :: Empty ; check_occurrences (psess , node_id , tt , & nested_macros , & nested_binders , & Stack :: Empty , guar ,) ; } (_ , tt) => { state = NestedMacroState :: Empty ; check_occurrences (psess , node_id , tt , macros , binders , ops , guar) ; } } } } #[doc = " Checks the body of nested macro, returns where the check stopped, and sets `valid` to false in"] #[doc = " case of errors."] #[doc = ""] #[doc = " The token trees are checked as long as they look like a list of (LHS) => {RHS} token trees. This"] #[doc = " check is a best-effort to detect a macro definition. It returns the position in `tts` where we"] #[doc = " stopped checking because we detected we were not in a macro definition anymore."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `psess` is used to emit diagnostics and lints"] #[doc = " - `node_id` is used to emit lints"] #[doc = " - `macro_rules` specifies whether the macro is `macro_rules`"] #[doc = " - `tts` is checked as a list of (LHS) => {RHS}"] #[doc = " - `macros` is the stack of outer macros"] #[doc = " - `guar` is set in case of errors"] fn check_nested_macro (psess : & ParseSess , node_id : NodeId , macro_rules : bool , tts : & [TokenTree] , macros : & Stack < '_ , MacroState < '_ > > , guar : & mut Option < ErrorGuaranteed > ,) -> usize { let n = tts . len () ; let mut i = 0 ; let separator = if macro_rules { TokenKind :: Semi } else { TokenKind :: Comma } ; loop { if i + 2 >= n || ! tts [i] . is_delimited () || ! tts [i + 1] . is_token (& TokenKind :: FatArrow) || ! tts [i + 2] . is_delimited () { break ; } let lhs = & tts [i] ; let rhs = & tts [i + 2] ; let mut binders = Binders :: default () ; check_binders (psess , node_id , lhs , macros , & mut binders , & Stack :: Empty , guar) ; check_occurrences (psess , node_id , rhs , macros , & binders , & Stack :: Empty , guar) ; i += 3 ; if i == n || ! tts [i] . is_token (& separator) { break ; } i += 1 ; } i } #[doc = " Checks that a meta-variable occurrence is valid."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `psess` is used to emit diagnostics and lints"] #[doc = " - `node_id` is used to emit lints"] #[doc = " - `macros` is the stack of possible outer macros"] #[doc = " - `binders` contains the binders of the associated LHS"] #[doc = " - `ops` is the stack of Kleene operators from the RHS"] #[doc = " - `span` is the span of the meta-variable to check"] #[doc = " - `name` is the name of the meta-variable to check"] fn check_ops_is_prefix (psess : & ParseSess , node_id : NodeId , macros : & Stack < '_ , MacroState < '_ > > , binders : & Binders , ops : & Stack < '_ , KleeneToken > , span : Span , name : MacroRulesNormalizedIdent ,) { let macros = macros . push (MacroState { binders , ops : ops . into () }) ; let mut acc : SmallVec < [& SmallVec < [KleeneToken ; 1] > ; 1] > = SmallVec :: new () ; for state in & macros { acc . push (& state . ops) ; if let Some (binder) = state . binders . get (& name) { let mut occurrence_ops : SmallVec < [KleeneToken ; 2] > = SmallVec :: new () ; for ops in acc . iter () . rev () { occurrence_ops . extend_from_slice (ops) ; } ops_is_prefix (psess , node_id , span , name , & binder . ops , & occurrence_ops) ; return ; } } buffer_lint (psess , span . into () , node_id , BuiltinLintDiag :: UnknownMacroVariable (name)) ; } #[doc = " Returns whether `binder_ops` is a prefix of `occurrence_ops`."] #[doc = ""] #[doc = " The stack of Kleene operators of a meta-variable occurrence just needs to have the stack of"] #[doc = " Kleene operators of its binder as a prefix."] #[doc = ""] #[doc = " Consider $i in the following example:"] #[doc = " ```ignore (illustrative)"] #[doc = " ( $( $i:ident = $($j:ident),+ );* ) => { $($( $i += $j; )+)* }"] #[doc = " ```"] #[doc = " It occurs under the Kleene stack [\"*\", \"+\"] and is bound under [\"*\"] only."] #[doc = ""] #[doc = " Arguments:"] #[doc = " - `psess` is used to emit diagnostics and lints"] #[doc = " - `node_id` is used to emit lints"] #[doc = " - `span` is the span of the meta-variable being check"] #[doc = " - `name` is the name of the meta-variable being check"] #[doc = " - `binder_ops` is the stack of Kleene operators for the binder"] #[doc = " - `occurrence_ops` is the stack of Kleene operators for the occurrence"] fn ops_is_prefix (psess : & ParseSess , node_id : NodeId , span : Span , name : MacroRulesNormalizedIdent , binder_ops : & [KleeneToken] , occurrence_ops : & [KleeneToken] ,) { for (i , binder) in binder_ops . iter () . enumerate () { if i >= occurrence_ops . len () { let mut span = MultiSpan :: from_span (span) ; span . push_span_label (binder . span , "expected repetition") ; buffer_lint (psess , span , node_id , BuiltinLintDiag :: MetaVariableStillRepeating (name)) ; return ; } let occurrence = & occurrence_ops [i] ; if occurrence . op != binder . op { let mut span = MultiSpan :: from_span (span) ; span . push_span_label (binder . span , "expected repetition") ; span . push_span_label (occurrence . span , "conflicting repetition") ; buffer_lint (psess , span , node_id , BuiltinLintDiag :: MetaVariableWrongOperator) ; return ; } } } fn buffer_lint (psess : & ParseSess , span : MultiSpan , node_id : NodeId , diag : BuiltinLintDiag) { if node_id != DUMMY_NODE_ID { psess . buffer_lint (META_VARIABLE_MISUSE , span , node_id , diag) ; } }